private suspend fun execute(command: String) {
    try {
        if (session != null && connected) {
            val channel = session?.openChannel("exec") as ChannelExec
            channel.setCommand(command)
            channel.connect()
            channel.disconnect()
        }
    } catch (e: Exception) {
        e.printStackTrace()
    }
}

