/// Connects to the current client through SFTP, uploads a file into it and then disconnects.
upload(File inputFile, String filename) async {
 Future.delayed(const Duration(seconds: 3));
 try {
   bool uploading = true;
   final sftp = await _client?.sftp();
   final file = await sftp?.open('/var/www/html/$filename',
       mode: SftpFileOpenMode.truncate |
           SftpFileOpenMode.create |
           SftpFileOpenMode.write);
   var fileSize = await inputFile.length();
   file?.write(inputFile.openRead().cast(), onProgress: (progress) {
     if(fileSize == progress){
       uploading = false;
     }
   });
   if(file==null){
      print('null');
      return;
   }
   await waitWhile(() => uploading);
 } catch (error) {
   if (kDebugMode) {
     print(error);
   }
 }
}

class SSH {
  late String _host;    //for IP Address
  late String _port;
  late String _username;
  late String _passwordOrKey;
  late String _numberOfVMs;
  SSHClient? _client;

  // Initialize connection details from shared preferences
  Future<void> initConnectionDetails() async {
    final SharedPreferences prefs = await SharedPreferences.getInstance();
    _host = prefs.getString('ipAddress') ?? '_host';
    _port = prefs.getString('sshPort') ?? '_port';
    _username = prefs.getString('username') ?? '_username';
    _passwordOrKey = prefs.getString('password') ?? '_passwordOrKey';
    _numberOfVMs = prefs.getString('numberOfVMs') ?? '_numberOfVMs';
  }

  // Connect to the Liquid Galaxy system
  Future<bool?> connectToLG() async {
    await initConnectionDetails();

    try {
      final socket = await SSHSocket.connect(_host, int.parse(_port));

      _client = SSHClient(
        socket,
        username: _username,
        onPasswordRequest: () => _passwordOrKey,
      );
      print(
          'IP : $_host, port : $_port, username : $_username, noOfVMs: $_numberOfVMs ');
      return true;
    } on SocketException catch (e) {
      print('Failed to connect: $e');
      return false;
    }
  }

