The generaterandompointswithinboundary() function generates random points within the boundary. It iterates until the desired number of points is reached. The random.uniform() function generates random longitude and latitude values.

def generate_random_points_within_boundary(boundary, n_points):
    points = []
    minx, miny, maxx, maxy = boundary.total_bounds
    while len(points) < n_points:
        random_point = Point(random.uniform(minx, maxx), random.uniform(miny, maxy))
        if boundary.contains(random_point).any():
            points.append(random_point)
    return points

