bool _orbitPlaying = false ;
Timer? _orbitTimer ;


Future<bool> orbitPlay(
   double latitude,
   double longitude,
   double zoom,
   double tilt,
   ) async {
 if (_orbitPlaying) {
   return false;
 }
 if (!_isConnected) {
   print('Cannot start orbit: LG not connected');
   return false;
 }
 await query('exittour=true');
 await Future.delayed(const Duration(milliseconds: 100));
 _orbitPlaying = true;
 try {
   const int steps = 60;
   const int stepDuration = 400;
   int currentStep = 1;
   bool isMoving = false;
   _orbitTimer = Timer.periodic(Duration(milliseconds: stepDuration), (
       timer,
       ) async {
     if (!_orbitPlaying || currentStep >= steps) {
       timer.cancel();
       _orbitPlaying = false;
       try {
         await query('exittour=true');
       } catch (e) {
         print('Error executing exittour after orbit completion: $e');
       }
       return;
     }
     if (isMoving) {
       return;
     }
     try {
       isMoving = true;
       double bearing = (currentStep * (360 / steps)) % 360;
       await flyToOrbit(
         'Orbit',
         latitude,
         longitude,
         zoom,
         tilt,
         bearing,
       ).timeout(const Duration(milliseconds: 100));
       currentStep++;
       isMoving = false;
     } catch (e) {
       print('Error during orbit step $currentStep: $e');
       currentStep++;
       isMoving = false;
     }
   });


   return true;
 } catch (e) {
   _orbitPlaying = false;
   //notifyListeners();
   print('Error during orbit: $e');
   return false;
 }
}

